values.content:
Synthesize hiring feedback into a scorecard.

Candidate: {{ $json.candidateName }}
Role: {{ $json.roleTitle }}
Seniority: {{ $json.seniorityLevel }}

Must-have criteria:
{{ $json.mustHaveCriteria.join('\n') || 'not specified' }}

Nice-to-have criteria:
{{ $json.niceToHaveCriteria.join('\n') || 'not specified' }}

Resume summary: {{ $json.resumeSummary || 'not provided' }}
Screening red flags: {{ $json.redFlagsFromScreening || 'none' }}

Interviewer feedback ({{ $json.feedbackCount }} interviews):
{{ $json.interviewerFeedback.map(f=>'--- '+f.interviewer+' ('+f.interviewType+') ---\nRecommendation: '+f.recommendation+'\nCompetencies assessed: '+f.competenciesAssessed.join(', ')+'\nNotes: '+f.notes).join('\n\n') }}

Return JSON:
{"overall_recommendation":"strong_hire|hire|lean_hire|lean_no_hire|no_hire","recommendation_confidence":"high|medium|low","synthesis_summary":"3-4 sentences: overall picture, where interviewers agree, where they diverge","criteria_assessment":[{"criterion":"","is_must_have":true,"evidence_for":["specific evidence from interviewer notes"],"evidence_against":["specific concerns from interviewer notes"],"verdict":"met|partially_met|not_met|insufficient_evidence"}],"interviewer_agreement":[{"topic":"","agreement_level":"strong_agreement|some_agreement|disagreement","details":""}],"disagreements_to_discuss":[{"topic":"","interviewer_positions":"who said what","suggested_resolution":"how to resolve this in debrief"}],"strengths":["specific, evidence-backed strengths"],"concerns":["specific, evidence-backed concerns"],"reference_check_questions":["specific things to verify with references based on interview signals"],"debrief_discussion_points":["what the hiring team should discuss before deciding"]}
